SOURCES = {
    "capital of japan": ("Tokyo", "https://example.org/japan"),
    "capital of peru": ("Lima", "https://example.org/peru"),
}

def lookup(query):
    answer, url = SOURCES.get(query.lower(), ("No result found", None))
    return {"answer": answer, "source": url}

citations = []
for q in ["capital of Japan", "capital of Peru", "capital of Mars"]:
    r = lookup(q)
    if r["source"]:
        citations.append(r["source"])
        print(f"{q}: {r['answer']} [{len(citations)}]")
    else:
        print(f"{q}: I couldn't find a source, so I won't guess.")

print("\nSources:")
for i, url in enumerate(citations, 1):
    print(f"[{i}] {url}")
